/// Interpolates every Skin Token, so a Theme or Skin change can be animated rather than snapping.
CbSkinTokens _lerpCbSkinTokens(CbSkinTokens a, CbSkinTokens b, double t) => CbSkinTokens(
  brand50: lerpCbOklch(a.brand50, b.brand50, t),
  brand100: lerpCbOklch(a.brand100, b.brand100, t),
  brand200: lerpCbOklch(a.brand200, b.brand200, t),
  brand300: lerpCbOklch(a.brand300, b.brand300, t),
  brand400: lerpCbOklch(a.brand400, b.brand400, t),
  brand500: lerpCbOklch(a.brand500, b.brand500, t),
  brand600: lerpCbOklch(a.brand600, b.brand600, t),
  brand700: lerpCbOklch(a.brand700, b.brand700, t),
  bg: lerpCbOklch(a.bg, b.bg, t),
  bgSubtle: lerpCbOklch(a.bgSubtle, b.bgSubtle, t),
  surface: lerpCbOklch(a.surface, b.surface, t),
  surfaceRaised: lerpCbOklch(a.surfaceRaised, b.surfaceRaised, t),
  border: lerpCbOklch(a.border, b.border, t),
  borderStrong: lerpCbOklch(a.borderStrong, b.borderStrong, t),
  fg: lerpCbOklch(a.fg, b.fg, t),
  fgMuted: lerpCbOklch(a.fgMuted, b.fgMuted, t),
  fgSubtle: lerpCbOklch(a.fgSubtle, b.fgSubtle, t),
  fgLink: lerpCbOklch(a.fgLink, b.fgLink, t),
  fgOnBrand: lerpCbOklch(a.fgOnBrand, b.fgOnBrand, t),
  toneNeutral: lerpCbOklch(a.toneNeutral, b.toneNeutral, t),
  toneBrand: lerpCbOklch(a.toneBrand, b.toneBrand, t),
  toneInfo: lerpCbOklch(a.toneInfo, b.toneInfo, t),
  toneSuccess: lerpCbOklch(a.toneSuccess, b.toneSuccess, t),
  toneWarning: lerpCbOklch(a.toneWarning, b.toneWarning, t),
  toneDanger: lerpCbOklch(a.toneDanger, b.toneDanger, t),
  decorViolet: lerpCbOklch(a.decorViolet, b.decorViolet, t),
  decorBlue: lerpCbOklch(a.decorBlue, b.decorBlue, t),
  decorTeal: lerpCbOklch(a.decorTeal, b.decorTeal, t),
  decorGreen: lerpCbOklch(a.decorGreen, b.decorGreen, t),
  decorAmber: lerpCbOklch(a.decorAmber, b.decorAmber, t),
  decorRose: lerpCbOklch(a.decorRose, b.decorRose, t),
  scrim: lerpCbOklch(a.scrim, b.scrim, t),
  scrimStrong: lerpCbOklch(a.scrimStrong, b.scrimStrong, t),
  onWarning: lerpCbOklch(a.onWarning, b.onWarning, t),
  shadowNone: lerpCbShadows(a.shadowNone, b.shadowNone, t),
  shadowSm: lerpCbShadows(a.shadowSm, b.shadowSm, t),
  shadowMd: lerpCbShadows(a.shadowMd, b.shadowMd, t),
  shadowLg: lerpCbShadows(a.shadowLg, b.shadowLg, t),
  paperBg: lerpCbOklch(a.paperBg, b.paperBg, t),
  paperBgWarm: lerpCbOklch(a.paperBgWarm, b.paperBgWarm, t),
  paperBorder: lerpCbOklch(a.paperBorder, b.paperBorder, t),
  paperFg: lerpCbOklch(a.paperFg, b.paperFg, t),
  paperTape: lerpCbOklch(a.paperTape, b.paperTape, t),
  paperShadow: lerpCbShadows(a.paperShadow, b.paperShadow, t),
  stickerShadow: lerpCbShadows(a.stickerShadow, b.stickerShadow, t),
  glassBg: lerpCbOklch(a.glassBg, b.glassBg, t),
  glassBgOpaque: lerpCbOklch(a.glassBgOpaque, b.glassBgOpaque, t),
  glassBorder: lerpCbOklch(a.glassBorder, b.glassBorder, t),
  glassBorderStrong: lerpCbOklch(a.glassBorderStrong, b.glassBorderStrong, t),
  glassBlur: lerpDouble(a.glassBlur, b.glassBlur, t)!,
  glassSaturation: lerpDouble(a.glassSaturation, b.glassSaturation, t)!,
  glassSpecular: lerpCbGradient(a.glassSpecular, b.glassSpecular, t),
  glassInset: lerpCbShadows(a.glassInset, b.glassInset, t),
  glassClearBg: lerpCbOklch(a.glassClearBg, b.glassClearBg, t),
  glassClearBorder: lerpCbOklch(a.glassClearBorder, b.glassClearBorder, t),
  glassClearBlur: lerpDouble(a.glassClearBlur, b.glassClearBlur, t)!,
  glassClearSaturation: lerpDouble(a.glassClearSaturation, b.glassClearSaturation, t)!,
  glassClearSpecular: lerpCbGradient(a.glassClearSpecular, b.glassClearSpecular, t),
  glassClearInset: lerpCbShadows(a.glassClearInset, b.glassClearInset, t),
  tintStrength: lerpDouble(a.tintStrength, b.tintStrength, t)!,
  gradientAngle: lerpDouble(a.gradientAngle, b.gradientAngle, t)!,
  fontSans: t < 0.5 ? a.fontSans : b.fontSans,
  fontMono: t < 0.5 ? a.fontMono : b.fontMono,
);

